(6711891, 1004379, 114225, '<td valign="top">Great color in the sky. A little more contrast may have helped the building pop out more.</td>', 'Great color in the sky. A little more contrast may have helped the building pop out more.', '2012-03-15 23:06:25.000000', NULL, 1),
(6711892, 1004197, 114225, '<td valign="top">Great perspective, and fine job making the lines of the buildings straight. Curvature here would have killed the effect.</td>', 'Great perspective, and fine job making the lines of the buildings straight. Curvature here would have killed the effect.', '2012-03-15 23:07:29.000000', NULL, 1),
(6712130, 1004426, 136168, '<td valign="top">beautiful light...</td>', 'beautiful light...', '2012-03-16 04:14:00.000000', NULL, 1),
(6712221, 1004072, 134859, '<td valign="top">very nice shot.  love the composition.   beautiful sky.  very nicely done.</td>', 'very nice shot.  love the composition.   beautiful sky.  very nicely done.', '2012-03-16 08:08:29.000000', NULL, 1),
(6712223, 1004336, 134859, '<td valign="top">lovely black and white.  I like how the buildings are towering over.  The angle you''ve taken this at is great... very fitting.</td>', 'lovely black and white.  I like how the buildings are towering over.  The angle you''ve taken this at is great... very fitting.', '2012-03-16 08:09:26.000000', NULL, 1),
(6712226, 1004382, 134859, '<td valign="top">nice shot.  I like the black and white.  The blurred foreground makes for an interesting framing of the photo.  well done</td>', 'nice shot.  I like the black and white.  The blurred foreground makes for an interesting framing of the photo.  well done', '2012-03-16 08:10:13.000000', NULL, 1),
(6712227, 1004151, 134859, '<td valign="top">very fitting title.  nice shot overall</td>', 'very fitting title.  nice shot overall', '2012-03-16 08:10:37.000000', NULL, 1),
(6712229, 1004333, 134859, '<td valign="top">This is unique to the challenge... which I like.  something different and out of the box.  nice detail and focus... just the right amount of color.  well done</td>', 'This is unique to the challenge... which I like.  something different and out of the box.  nice detail and focus... just the right amount of color.  well done', '2012-03-16 08:11:35.000000', NULL, 1),
(6712231, 1004385, 134859, '<td valign="top">a cool shot... but a bit over processed to me.</td>', 'a cool shot... but a bit over processed to me.', '2012-03-16 08:12:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6712232, 1003338, 134859, '<td valign="top">nice black and white.  I like the starburst of light on the lamp.  A sad sight, as it seems the factory is run down and out of business?  well shot</td>', 'nice black and white.  I like the starburst of light on the lamp.  A sad sight, as it seems the factory is run down and out of business?  well shot', '2012-03-16 08:13:30.000000', NULL, 1),
(6712234, 1003845, 134859, '<td valign="top">lovely shot.  I like how the light, literally, leads the way.  nice title choice.<br/>good detail and focus.</td>', 'lovely shot.  I like how the light, literally, leads the way.  nice title choice.good detail and focus.', '2012-03-16 08:14:36.000000', NULL, 1),
(6712235, 1003479, 134859, '<td valign="top">a pretty, retro-feeling shot.  love what you''ve done here.  well done</td>', 'a pretty, retro-feeling shot.  love what you''ve done here.  well done', '2012-03-16 08:15:20.000000', NULL, 1),
(6712237, 1004408, 134859, '<td valign="top">bright lights everywhere... I like it.  and I really like how you''ve captured the city behind the homelife.  nicely done</td>', 'bright lights everywhere... I like it.  and I really like how you''ve captured the city behind the homelife.  nicely done', '2012-03-16 08:16:10.000000', NULL, 1),
(6712383, 1004358, 146206, '<td valign="top">Nice!!</td>', 'Nice!!', '2012-03-16 10:29:35.000000', NULL, 1),
(6712384, 1004110, 146206, '<td valign="top">Very nice!</td>', 'Very nice!', '2012-03-16 10:34:27.000000', NULL, 1),
(6712433, 1004296, 134859, '<td valign="top">great shot.  love the differentness of the culture and the yellow adds that little pop that makes the photo even better.</td>', 'great shot.  love the differentness of the culture and the yellow adds that little pop that makes the photo even better.', '2012-03-16 11:08:01.000000', NULL, 1),
(6712434, 1004258, 134859, '<td valign="top">beautiful serene shot.  love the color in the water</td>', 'beautiful serene shot.  love the color in the water', '2012-03-16 11:08:44.000000', NULL, 1),
(6712436, 1004090, 134859, '<td valign="top">love the wide shot.  nice colors.  perhaps a little sharper and it would have been even better</td>', 'love the wide shot.  nice colors.  perhaps a little sharper and it would have been even better', '2012-03-16 11:09:37.000000', NULL, 1),
(6712438, 1004356, 134859, '<td valign="top">love the angle of this shot and the uniqueness of the structure!  wonderfully done</td>', 'love the angle of this shot and the uniqueness of the structure!  wonderfully done', '2012-03-16 11:10:13.000000', NULL, 1),
(6712439, 1004412, 134859, '<td valign="top">lovely shot.  pretty colors.</td>', 'lovely shot.  pretty colors.', '2012-03-16 11:10:40.000000', NULL, 1),
(6712440, 1004398, 134859, '<td valign="top">this reminds me of the tragedy of the twin towers being hit.  it''s dark, looks Smokey but perhaps it''s just the clouds.  I can kind of make out a building to the right... very intense photo.  10</td>', 'this reminds me of the tragedy of the twin towers being hit.  it''s dark, looks Smokey but perhaps it''s just the clouds.  I can kind of make out a building to the right... very intense photo.  10', '2012-03-16 11:12:07.000000', NULL, 1),
(6712441, 1004465, 134859, '<td valign="top">very different shot.  outside of the box.  nice grayscale.  would have liked to have seen the fence a little more level.</td>', 'very different shot.  outside of the box.  nice grayscale.  would have liked to have seen the fence a little more level.', '2012-03-16 11:13:06.000000', NULL, 1),
(6712445, 1004387, 134859, '<td valign="top">beautiful portrayal of how places are urbanized.  love the wide shot!</td>', 'beautiful portrayal of how places are urbanized.  love the wide shot!', '2012-03-16 11:14:01.000000', NULL, 1),
(6712447, 1004280, 134859, '<td valign="top">nice shot.  I think the angle could have been a little different, putting more of the bridge in focus, but a good shot nonetheless</td>', 'nice shot.  I think the angle could have been a little different, putting more of the bridge in focus, but a good shot nonetheless', '2012-03-16 11:15:11.000000', NULL, 1),
(6712460, 1004429, 136168, '<td valign="top">I like this image...see it as a struggle between nature and urbanisation...</td>', 'I like this image...see it as a struggle between nature and urbanisation...', '2012-03-16 11:28:07.000000', NULL, 1),
(6712464, 1004431, 136168, '<td valign="top">awesome diversity of shapes/lines and tonality</td>', 'awesome diversity of shapes/lines and tonality', '2012-03-16 11:30:07.000000', NULL, 1),
(6712880, 1004240, 134859, '<td valign="top">Very bright lights.  I like the wideness of the photo, I think perhaps if it were a little sharper it would have really looked outstanding.</td>', 'Very bright lights.  I like the wideness of the photo, I think perhaps if it were a little sharper it would have really looked outstanding.', '2012-03-16 17:03:14.000000', NULL, 1),
(6712882, 1003684, 134859, '<td valign="top">Awesome shot!  Love the lines and the outside of the box thinking with this shot.  Not a cityscape, but definitely within a city.  Great job</td>', 'Awesome shot!  Love the lines and the outside of the box thinking with this shot.  Not a cityscape, but definitely within a city.  Great job', '2012-03-16 17:03:47.000000', NULL, 1),
(6712885, 1003405, 134859, '<td valign="top">A lovely shot.  The sky is beautiful, I haven''t been able to shoot a sky at night and still obtain the stars (yet).  Another goal to achieve.  <br/>I love the angle of the bridge, the softness and glow of the water.  Beautiful shot.</td>', 'A lovely shot.  The sky is beautiful, I haven''t been able to shoot a sky at night and still obtain the stars (yet).  Another goal to achieve.  I love the angle of the bridge, the softness and glow of the water.  Beautiful shot.', '2012-03-16 17:04:35.000000', NULL, 1),
(6712890, 1004311, 134859, '<td valign="top">A lovely shot.  I have always wanted to visit Sydney, and this picture makes me want to visit that much more.  The colors are beautiful... LOVE the reflections in the water.  The bright lights against the dark skies.  Well done</td>', 'A lovely shot.  I have always wanted to visit Sydney, and this picture makes me want to visit that much more.  The colors are beautiful... LOVE the reflections in the water.  The bright lights against the dark skies.  Well done', '2012-03-16 17:05:35.000000', NULL, 1),
(6712895, 1004238, 134859, '<td valign="top">Absolutely amazing shot.  Really, it''s breathtaking.  Almost like a painting.  <br/>Love the flock of birds, the PP that was involved, the lighting, the detail... everything about it speaks of classical feel.  Great shot.  Very well done!<br/>And the title couldn''t be better!  10</td>', 'Absolutely amazing shot.  Really, it''s breathtaking.  Almost like a painting.  Love the flock of birds, the PP that was involved, the lighting, the detail... everything about it speaks of classical feel.  Great shot.  Very well done!And the title couldn''t be better!  10', '2012-03-16 17:06:37.000000', NULL, 1),
(6712897, 1004150, 134859, '<td valign="top">Very interesting shot.  Love the darkness and the light hitting the building.  Nice detail and sharpness in the picture as well.</td>', 'Very interesting shot.  Love the darkness and the light hitting the building.  Nice detail and sharpness in the picture as well.', '2012-03-16 17:07:04.000000', NULL, 1),
(6712900, 1004004, 134859, '<td valign="top">Love the soft flow of the water in this photo.  If the background was sharper, while the foreground was soft, then it would really stand out.  Great light, beautiful color.  Well shot.</td>', 'Love the soft flow of the water in this photo.  If the background was sharper, while the foreground was soft, then it would really stand out.  Great light, beautiful color.  Well shot.', '2012-03-16 17:07:41.000000', NULL, 1),
(6712905, 1003842, 134859, '<td valign="top">Wow... I couldn''t'' imagine living somewhere like this.  WAY TOO MUCH GOING ON (citywide, not photo wise).<br/>Beautiful shot.  Love the surfer in the foreground.  The people walking on the beach.  The homes and power lines, and everything.  It''s a great shot.</td>', 'Wow... I couldn''t'' imagine living somewhere like this.  WAY TOO MUCH GOING ON (citywide, not photo wise).Beautiful shot.  Love the surfer in the foreground.  The people walking on the beach.  The homes and power lines, and everything.  It''s a great shot.', '2012-03-16 17:08:42.000000', NULL, 1),
(6712909, 1003685, 134859, '<td valign="top">Very cool angle.  Not sure that I''m feeling the PP... but it''s interesting, that''s for sure.  I like the outside of the box thinking.  The idea is great!  Still, it deserves at least an 8 for creativity and such.  :)</td>', 'Very cool angle.  Not sure that I''m feeling the PP... but it''s interesting, that''s for sure.  I like the outside of the box thinking.  The idea is great!  Still, it deserves at least an 8 for creativity and such.  :)', '2012-03-16 17:09:43.000000', NULL, 1),
(6712911, 1004115, 134859, '<td valign="top">Lovely shot.  Looks like it may be a little unlevel (?)  But I love the darkness against the light.  Overall, it''s a very nice shot.</td>', 'Lovely shot.  Looks like it may be a little unlevel (?)  But I love the darkness against the light.  Overall, it''s a very nice shot.', '2012-03-16 17:10:14.000000', NULL, 1),
(6712914, 1004110, 134859, '<td valign="top">I like the idea here, the cross in the foreground, the city in the background... the "cursed" implication.  The red, I am sure is done to reiterate that fact, but I think it''s a little too much.  Then again, that''s just this gal''s opinion.  :)  Still, very nicely shot.</td>', 'I like the idea here, the cross in the foreground, the city in the background... the "cursed" implication.  The red, I am sure is done to reiterate that fact, but I think it''s a little too much.  Then again, that''s just this gal''s opinion.  :)  Still, very nicely shot.', '2012-03-16 17:11:09.000000', NULL, 1),
(6712918, 1004250, 134859, '<td valign="top">Lol.  Love the title and the fact that the sight is only half there.  <br/>Great shot.  Very unique.  <br/>Love the city feel here.  <br/>Nicely done.</td>', 'Lol.  Love the title and the fact that the sight is only half there.  Great shot.  Very unique.  Love the city feel here.  Nicely done.', '2012-03-16 17:11:48.000000', NULL, 1),
(6712920, 1004256, 134859, '<td valign="top">Beautiful shot.  Not too much going on.  Not too much color.  Just simple, modern, and beautiful!</td>', 'Beautiful shot.  Not too much going on.  Not too much color.  Just simple, modern, and beautiful!', '2012-03-16 17:12:12.000000', NULL, 1),
(6712938, 1004468, 134859, '<td valign="top">Nice colors.  Love the black of the buildings with with blues, purples, reds, and pinks.  Very nicely done.</td>', 'Nice colors.  Love the black of the buildings with with blues, purples, reds, and pinks.  Very nicely done.', '2012-03-16 17:22:19.000000', NULL, 1),
(6712939, 1003667, 134859, '<td valign="top">Cool shot.  Not sure that everyone will agree, but it''s simplistic yet telling.</td>', 'Cool shot.  Not sure that everyone will agree, but it''s simplistic yet telling.', '2012-03-16 17:22:51.000000', NULL, 1),
(6712942, 1003916, 134859, '<td valign="top">Love the trolley (?) whooshing by.  Nice shot, including bikes, the people walking, the angle of the shot, the tilted nature.  Well done.</td>', 'Love the trolley (?) whooshing by.  Nice shot, including bikes, the people walking, the angle of the shot, the tilted nature.  Well done.', '2012-03-16 17:23:35.000000', NULL, 1),
(6712948, 1004147, 134859, '<td valign="top">A sad picture.  There are many places like that around here.  it''s depressing to see.  But, it''s history.  <br/>I like the shot overall.  There are a few things I would have done differently, such as the colors, sharpness, exposure.  But I like the idea, and the composure.</td>', 'A sad picture.  There are many places like that around here.  it''s depressing to see.  But, it''s history.  I like the shot overall.  There are a few things I would have done differently, such as the colors, sharpness, exposure.  But I like the idea, and the composure.', '2012-03-16 17:24:36.000000', NULL, 1),
(6712950, 1003897, 134859, '<td valign="top">Can barely see the white horse.  I like the city in the background.  I don''t think this was the best angle, as at the bottom of the picture, it seems to be tall grass or bushes that were cut off.  There''s also a lot of "plain" sky... which I think takes away from the photo.  But a good attempt.</td>', 'Can barely see the white horse.  I like the city in the background.  I don''t think this was the best angle, as at the bottom of the picture, it seems to be tall grass or bushes that were cut off.  There''s also a lot of "plain" sky... which I think takes away from the photo.  But a good attempt.', '2012-03-16 17:25:34.000000', NULL, 1),
(6712952, 1004218, 134859, '<td valign="top">A little too OOF for my liking.  I like the idea, but I think with a little more sharpness, the photo could have really popped.</td>', 'A little too OOF for my liking.  I like the idea, but I think with a little more sharpness, the photo could have really popped.', '2012-03-16 17:25:56.000000', NULL, 1),
(6712954, 1004098, 134859, '<td valign="top">Was this taken from a plane, or helicopter?  Cool if it was.  I like the view of the shot, but the PP, not so much.</td>', 'Was this taken from a plane, or helicopter?  Cool if it was.  I like the view of the shot, but the PP, not so much.', '2012-03-16 17:26:22.000000', NULL, 1),
(6712955, 1004340, 134859, '<td valign="top">Lots of lights.  I am not too fond of the bland foreground.  perhaps if it was blurred out so it wouldn''t serve as a distraction.  Also, it seems a little OOF.  But I like the idea of the shot.</td>', 'Lots of lights.  I am not too fond of the bland foreground.  perhaps if it was blurred out so it wouldn''t serve as a distraction.  Also, it seems a little OOF.  But I like the idea of the shot.', '2012-03-16 17:27:06.000000', NULL, 1),
(6712957, 1004429, 134859, '<td valign="top">Not anything I find visually appealing, but that''s just me.  I think if the fence was blurred, and the rest was in focus, it would have looked better.  But I can get the sense that perhaps, you kept the "pretty" in focus, and let the "ugly" be out of focus.</td>', 'Not anything I find visually appealing, but that''s just me.  I think if the fence was blurred, and the rest was in focus, it would have looked better.  But I can get the sense that perhaps, you kept the "pretty" in focus, and let the "ugly" be out of focus.', '2012-03-16 17:27:54.000000', NULL, 1),
(6712958, 1004209, 134859, '<td valign="top">I like this, but I think the lighting is a little too bright, and the color of the statue seems a little bland.  Also, the bottom of the foot is cut off, and part of it is OOF.  I think if the background would have been OOF, and the statue sharper and more colorful (or even saturated), it would have really stood out.</td>', 'I like this, but I think the lighting is a little too bright, and the color of the statue seems a little bland.  Also, the bottom of the foot is cut off, and part of it is OOF.  I think if the background would have been OOF, and the statue sharper and more colorful (or even saturated), it would have really stood out.', '2012-03-16 17:29:05.000000', NULL, 1),
(6712961, 1004269, 134859, '<td valign="top">Interesting shot.  Looks like the smudges of windshield wipers, as the photographer is looking out into the city, field, etc.  Oddly, I like it.  :)</td>', 'Interesting shot.  Looks like the smudges of windshield wipers, as the photographer is looking out into the city, field, etc.  Oddly, I like it.  :)', '2012-03-16 17:29:43.000000', NULL, 1),
(6712963, 1002917, 134859, '<td valign="top">Noisy, gray, OOF, I like it.  So completely different, abstract, imagination can run wild with it.</td>', 'Noisy, gray, OOF, I like it.  So completely different, abstract, imagination can run wild with it.', '2012-03-16 17:30:09.000000', NULL, 1),
(6712964, 1004230, 134859, '<td valign="top">Seems like everything is OOF here.  I like the sunset and trees, I even like the shot in general, I think that if it would have been sharper, it would have really looked nice.</td>', 'Seems like everything is OOF here.  I like the sunset and trees, I even like the shot in general, I think that if it would have been sharper, it would have really looked nice.', '2012-03-16 17:30:38.000000', NULL, 1),
(6712965, 1004297, 134859, '<td valign="top">Very interesting shot.  I like how you can see the city in the reflection, I just would have liked to see more "reflection", a glassier appearance.</td>', 'Very interesting shot.  I like how you can see the city in the reflection, I just would have liked to see more "reflection", a glassier appearance.', '2012-03-16 17:31:07.000000', NULL, 1),
(6712966, 1004470, 134859, '<td valign="top">Upside down swan.  That''s odd.  I do think the idea is cool, with the homes in reflection.  The color is nice, and the ripples make the picture more interesting.</td>', 'Upside down swan.  That''s odd.  I do think the idea is cool, with the homes in reflection.  The color is nice, and the ripples make the picture more interesting.', '2012-03-16 17:31:48.000000', NULL, 1),
(6713092, 1004379, 69324, '<td valign="top">Very nicely processed.</td>', 'Very nicely processed.', '2012-03-16 19:17:19.000000', NULL, 1),
(6713296, 1004123, 114225, '<td valign="top">Great choice for black and white.</td>', 'Great choice for black and white.', '2012-03-16 21:51:26.000000', NULL, 1),
(6713319, 1004256, 16148, '<td valign="top">Interesting patterns with the trees on the left and series of lights.</td>', 'Interesting patterns with the trees on the left and series of lights.', '2012-03-16 22:06:23.000000', NULL, 1),
(6713340, 1004446, 16148, '<td valign="top">I''n not crazy about your crop on the bottom.  Interesting shot besides that.</td>', 'I''n not crazy about your crop on the bottom.  Interesting shot besides that.', '2012-03-16 22:18:30.000000', NULL, 1),
(6713349, 1004314, 16148, '<td valign="top">Reminds me of Franz Kline.</td>', 'Reminds me of Franz Kline.', '2012-03-16 22:23:11.000000', NULL, 1),
(6713355, 1004266, 16148, '<td valign="top">Solid shot!  Very well done.</td>', 'Solid shot!  Very well done.', '2012-03-16 22:25:23.000000', NULL, 1),
(6713407, 1004333, 30982, '<td valign="top">Very much my kind of shot.  Excellent interpretation.  These things fascinate me and I''m glad I''m not the only one who notices them.</td>', 'Very much my kind of shot.  Excellent interpretation.  These things fascinate me and I''m glad I''m not the only one who notices them.', '2012-03-16 22:44:56.000000', NULL, 1),
(6713411, 1004464, 30982, '<td valign="top">I like the oddly retro-ish solarization.  I want to think this is a bit of an ironic shot, taken and processed with a cell phone, with it''s lowly corded cousin as the subject.</td>', 'I like the oddly retro-ish solarization.  I want to think this is a bit of an ironic shot, taken and processed with a cell phone, with it''s lowly corded cousin as the subject.', '2012-03-16 22:46:10.000000', NULL, 1),
(6713469, 1003875, 30982, '<td valign="top">Probably not urban enough for some, but cities differ - and can still be "cities".  I love the "border" of water...  Really a lovely photograph.  Peaceful but full of implied life.</td>', 'Probably not urban enough for some, but cities differ - and can still be "cities".  I love the "border" of water...  Really a lovely photograph.  Peaceful but full of implied life.', '2012-03-16 23:09:45.000000', NULL, 1),
(6713473, 1003793, 30982, '<td valign="top">Gorgeous city - almost cheating, it''s so pretty!</td>', 'Gorgeous city - almost cheating, it''s so pretty!', '2012-03-16 23:10:27.000000', NULL, 1),
(6713474, 1004387, 30982, '<td valign="top">Awesome viewpoint!</td>', 'Awesome viewpoint!', '2012-03-16 23:10:39.000000', NULL, 1),
(6713475, 1004296, 30982, '<td valign="top">Nicely real.</td>', 'Nicely real.', '2012-03-16 23:10:48.000000', NULL, 1),
(6713477, 1004288, 30982, '<td valign="top">Amsterdam would be my guess.  I like your choice of B&amp;W for this.</td>', 'Amsterdam would be my guess.  I like your choice of B&W for this.', '2012-03-16 23:11:18.000000', NULL, 1),
(6713478, 1003069, 30982, '<td valign="top">Nice use of the bridge for framing and excellent choice in time of day.</td>', 'Nice use of the bridge for framing and excellent choice in time of day.', '2012-03-16 23:11:40.000000', NULL, 1),
(6713480, 1004356, 30982, '<td valign="top">Something intriguing about the one building reaching to the other... Then there''s the mystery of the light...</td>', 'Something intriguing about the one building reaching to the other... Then there''s the mystery of the light...', '2012-03-16 23:12:18.000000', NULL, 1),
(6713483, 1004467, 30982, '<td valign="top">Ha!  Great title!  Really a very fitting landscape, too.</td>', 'Ha!  Great title!  Really a very fitting landscape, too.', '2012-03-16 23:12:50.000000', NULL, 1),
(6713484, 1004429, 30982, '<td valign="top">That one little butterfly surrounded by the blight... nice find, nice story to present.</td>', 'That one little butterfly surrounded by the blight... nice find, nice story to present.', '2012-03-16 23:13:16.000000', NULL, 1),
(6713486, 1004258, 30982, '<td valign="top">Really a nice sense of calm.  Love the birds on his boat.</td>', 'Really a nice sense of calm.  Love the birds on his boat.', '2012-03-16 23:13:36.000000', NULL, 1),
(6713489, 1004138, 30982, '<td valign="top">I love fog.  Nice use of the railed fence to add a good dose of contrast.</td>', 'I love fog.  Nice use of the railed fence to add a good dose of contrast.', '2012-03-16 23:13:56.000000', NULL, 1),
(6713492, 1004470, 30982, '<td valign="top">The shadow city and the shadow goose give just enough weight to suspend the upsidedownedness of the real-life bird.</td>', 'The shadow city and the shadow goose give just enough weight to suspend the upsidedownedness of the real-life bird.', '2012-03-16 23:14:34.000000', NULL, 1),
(6713493, 1004168, 30982, '<td valign="top">Really lovely - this would make a nice print to hang somewhere you wanted folks to have a sense of calm.  Nicely composed - has a very good flow to it - puts me there.</td>', 'Really lovely - this would make a nice print to hang somewhere you wanted folks to have a sense of calm.  Nicely composed - has a very good flow to it - puts me there.', '2012-03-16 23:15:18.000000', NULL, 1),
(6713498, 1004359, 30982, '<td valign="top">Excellent expression!  And I love the cars parked around.  One wonders what in the world the kneepads are for.  No idea if anyone will see this as an urban landscape but I think it fits the bill nicely!</td>', 'Excellent expression!  And I love the cars parked around.  One wonders what in the world the kneepads are for.  No idea if anyone will see this as an urban landscape but I think it fits the bill nicely!', '2012-03-16 23:15:54.000000', NULL, 1),
