(6717138, 1004095, 12611, '<td valign="top">wonderful neighborhood shot.</td>', 'wonderful neighborhood shot.', '2012-03-20 08:40:34.000000', NULL, 1),
(6717139, 1004004, 12611, '<td valign="top">Nice exposure.</td>', 'Nice exposure.', '2012-03-20 08:41:05.000000', NULL, 1),
(6717144, 1004251, 12611, '<td valign="top">The composition is flawless, from the perfect placement of that teal building to the horse and topiary details, the subtle HDR feel really works. Has a "morning in Philadelphia" sort of feel to it, (regardless of the location, if I am wrong!)</td>', 'The composition is flawless, from the perfect placement of that teal building to the horse and topiary details, the subtle HDR feel really works. Has a "morning in Philadelphia" sort of feel to it, (regardless of the location, if I am wrong!)', '2012-03-20 08:48:40.000000', NULL, 1),
(6717150, 1003916, 12611, '<td valign="top">Great colors.</td>', 'Great colors.', '2012-03-20 08:56:13.000000', NULL, 1),
(6717151, 1003667, 12611, '<td valign="top">That car/van on the left makes the shot. excellent details.</td>', 'That car/van on the left makes the shot. excellent details.', '2012-03-20 08:56:50.000000', NULL, 1),
(6717152, 1004469, 12611, '<td valign="top">Dreamy feel. Very pleasing image.</td>', 'Dreamy feel. Very pleasing image.', '2012-03-20 08:57:30.000000', NULL, 1),
(6717153, 1004258, 12611, '<td valign="top">Those details are stunning, and you have nicely grayed out the whole image. Stunning work.</td>', 'Those details are stunning, and you have nicely grayed out the whole image. Stunning work.', '2012-03-20 08:58:32.000000', NULL, 1),
(6717154, 1004436, 12611, '<td valign="top">The big square instagram framing works. Good slice of life, great title, interesting image.</td>', 'The big square instagram framing works. Good slice of life, great title, interesting image.', '2012-03-20 08:59:30.000000', NULL, 1),
(6717156, 1002917, 12611, '<td valign="top">Like the cities demons manifesting into a ghostly meerkat.</td>', 'Like the cities demons manifesting into a ghostly meerkat.', '2012-03-20 09:00:29.000000', NULL, 1),
(6717158, 1004151, 12611, '<td valign="top">sad commentary for sure.</td>', 'sad commentary for sure.', '2012-03-20 09:04:02.000000', NULL, 1),
(6717161, 1004333, 12611, '<td valign="top">Kind of reminds me of Otto Steinert. <a href="//www.google.com/imgres?hl=en&amp;safe=active&amp;gbv=2&amp;tbm=isch&amp;tbnid=xNrSStvCQpaOxM:&amp;imgrefurl=//www.vulgare.net/unijambiste-by-otto-steinert-1950/&amp;docid=4DD4TC_3TfR7fM&amp;imgurl=//www.vulgare.net/wp-content/uploads/2012/01/rosa6-15-3.jpg&amp;w=432&amp;h=284&amp;ei=Q4FoT_W7D8KC0QHGy9ixCQ&amp;zoom=1&amp;iact=rc&amp;dur=733&amp;sig=106645437193291792619&amp;page=1&amp;tbnh=139&amp;tbnw=185&amp;start=0&amp;ndsp=35&amp;ved=1t:429,r:0,s:0&amp;tx=77&amp;ty=39&amp;biw=1474&amp;bih=768" rel="nofollow" target="_blank">Steinert link</a> <br/> <br/>but, I like the darkness and depth and reflections in yours.</td>', 'Kind of reminds me of Otto Steinert. Steinert link  but, I like the darkness and depth and reflections in yours.', '2012-03-20 09:09:48.000000', NULL, 1),
(6717163, 1003795, 12611, '<td valign="top">Beautiful shapes and contrast. The "through the glass" feel in the upper left gives a classic feel to the shot.</td>', 'Beautiful shapes and contrast. The "through the glass" feel in the upper left gives a classic feel to the shot.', '2012-03-20 09:11:44.000000', NULL, 1),
(6717166, 1004256, 12611, '<td valign="top">that row of trees on the left is a good addition to the shot. There is a feeling of brown stillness.</td>', 'that row of trees on the left is a good addition to the shot. There is a feeling of brown stillness.', '2012-03-20 09:16:59.000000', NULL, 1),
(6717169, 1004138, 12611, '<td valign="top">I am not sure about that title, but the shot is fantastic. The reflection in the near left side and the trees on the right stand out. Great composition and exposure.</td>', 'I am not sure about that title, but the shot is fantastic. The reflection in the near left side and the trees on the right stand out. Great composition and exposure.', '2012-03-20 09:18:21.000000', NULL, 1),
(6717170, 1004310, 12611, '<td valign="top">Is that a toilet seat on there? thats a good touch.</td>', 'Is that a toilet seat on there? thats a good touch.', '2012-03-20 09:19:10.000000', NULL, 1),
(6717175, 1003667, 31637, '<td valign="top">Love the capture of Jupiter and Venus. But that glare in the center of the building distracts and the exposure needs work.</td>', 'Love the capture of Jupiter and Venus. But that glare in the center of the building distracts and the exposure needs work.', '2012-03-20 09:45:38.000000', NULL, 1),
