(6717271, 1004408, 10785, '<td valign="top">Superb use of DoF here, but I think it isn''t quite sharp enough where it needs to be. Love how the townhomes look miniature! The composition is great too! Nice lines and layers!</td>', 'Superb use of DoF here, but I think it isn''t quite sharp enough where it needs to be. Love how the townhomes look miniature! The composition is great too! Nice lines and layers!', '2012-03-20 11:34:17.000000', NULL, 1),
(6717272, 1004095, 10785, '<td valign="top">This pretty much falls into the genre of suburban pet photography, not really urban landscape!</td>', 'This pretty much falls into the genre of suburban pet photography, not really urban landscape!', '2012-03-20 11:35:59.000000', NULL, 1),
(6717275, 1003897, 74588, '<td valign="top">cant see the horse,maybe have to get new glasses.     8</td>', 'cant see the horse,maybe have to get new glasses.     8', '2012-03-20 11:39:17.000000', NULL, 1),
(6717277, 1004200, 10785, '<td valign="top">Awesomne landscape! I love the tones and the raod makes for great leading lines to the mountain range!  Just one nit-pick to mention about the details... watch out for that foreground scrub. I think cropping that out or reframing the shot to get that out would have made the shot just that much more clean and neat. But it is minor. It does look like you waited for just the right moment to get the cars to be ordered well in the shot!</td>', 'Awesomne landscape! I love the tones and the raod makes for great leading lines to the mountain range!  Just one nit-pick to mention about the details... watch out for that foreground scrub. I think cropping that out or reframing the shot to get that out would have made the shot just that much more clean and neat. But it is minor. It does look like you waited for just the right moment to get the cars to be ordered well in the shot!', '2012-03-20 11:40:26.000000', NULL, 1),
(6717278, 1004470, 74588, '<td valign="top">i think the white swan is to prominent for it to work   8</td>', 'i think the white swan is to prominent for it to work   8', '2012-03-20 11:41:35.000000', NULL, 1),
(6717279, 1004436, 74588, '<td valign="top">maybe a bit to flat?     7</td>', 'maybe a bit to flat?     7', '2012-03-20 11:42:33.000000', NULL, 1),
(6717281, 1004269, 10785, '<td valign="top">It''s interesting with a little color and texture. But not exactly right for the urban landscape genre. It''s clearly a good abstract.</td>', 'It''s interesting with a little color and texture. But not exactly right for the urban landscape genre. It''s clearly a good abstract.', '2012-03-20 11:43:21.000000', NULL, 1),
(6717284, 1004446, 10785, '<td valign="top">Very tilted. Good color!</td>', 'Very tilted. Good color!', '2012-03-20 11:44:05.000000', NULL, 1),
(6717285, 1004398, 10785, '<td valign="top">A very interesting shot with great tones and textures. It is missing the urban landscape, but if you were shooting for a sky scape or an abstract challenge, this would do wonderfully!</td>', 'A very interesting shot with great tones and textures. It is missing the urban landscape, but if you were shooting for a sky scape or an abstract challenge, this would do wonderfully!', '2012-03-20 11:45:38.000000', NULL, 1),
(6717287, 1003685, 10785, '<td valign="top">Your use of the bright spot to create a focal point is too accentuated. It needs to be a little more subtle.</td>', 'Your use of the bright spot to create a focal point is too accentuated. It needs to be a little more subtle.', '2012-03-20 11:50:03.000000', NULL, 1),
(6717305, 1002917, 10785, '<td valign="top">Call me un-enlightened, but I am not really catching the vision of your shot.</td>', 'Call me un-enlightened, but I am not really catching the vision of your shot.', '2012-03-20 12:09:51.000000', NULL, 1),
